Here is a net/http handler that does this:
```
package main

import (
	"fmt"
	"log"
	"net/http"
	"net/url"
	"strings"
)

func main() {
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "GET" {
			http.Error(w, "Only GET requests are supported", http.StatusMethodNotAllowed)
			return
		}

		hostname := r.URL.Path[1:]
		if hostname == "" {
			http.Error(w, "Hostname is required", http.StatusBadRequest)
			return
		}

		hostname = strings.Trim(hostname, "/")

		ips := []string{}
		ips = append(ips, resolve("8.8.8.8", hostname)...)
		ips = append(ips, resolve("1.1.1.1", hostname)...)

		fmt.Fprintf(w, "Hostnames: %s\n", hostname)
		fmt.Fprintf(w, "IPs: %s\n", strings.Join(ips, ", "))

		hostnameToIPs := make(map[string][]string)
		hostnameToIPs[hostname] = ips
	})
	http.ListenAndServe(":8080", nil)
}

func resolve(dnsServer string, hostname string) []string {
	u, err := url.Parse("dns://" + dnsServer + "/" + hostname)
	if err != nil {
		log.Fatal(err)
	}
	resp, err := http.Get(u.String())
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()

	var ips []string
	for _, line := range strings.Split(strings.TrimSpace(resp.Body.String()), "\n") {
		if strings.HasPrefix(line, "ANSWER") {
			ips = append(ips, strings.TrimSpace(line[6:]))
		}
	}
	return ips
}
```
